import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
CUR = {'TL': ('Türk Lirası', 'lira', 'kuruş'), 'USD': ('Dolar', 'dolar', 'sent'), 'EUR': ('Euro', 'euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'sterlin', 'peni')}
def money(x, c):
    full, unit, sub = CUR[c]
    cents = int(round(abs(float(x)) * 100))
    a, b = divmod(cents, 100)
    if b == 0:
        return words(a) + ' ' + full
    return words(a) + ' ' + unit + ' ' + words(b) + ' ' + sub
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if not d:
        return str(s)
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def suffix_dir(s):
    d = pdate(s)
    last = words(d.year).split()[-1] if d else 'altı'
    vow = [ch for ch in last if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'a'
    hv = {'a': 'ı', 'ı': 'ı', 'e': 'i', 'i': 'i', 'o': 'u', 'u': 'u', 'ö': 'ü', 'ü': 'ü'}[v]
    c = 't' if last[-1] in 'fstkçşhp' else 'd'
    return "'" + c + hv + 'r'
def digits(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
def today():
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def num(b, k):
    try:
        return float((b or {}).get(k) or 0)
    except Exception:
        return 0.0
def body_of(result):
    d = result.get('data') if isinstance(result, dict) else None
    if isinstance(d, str):
        try:
            d = json.loads(d)
        except Exception:
            d = None
    return d if isinstance(d, dict) else {}
def ok_of(result):
    b = body_of(result)
    sc = result.get('status_code') if isinstance(result, dict) else None
    try:
        sc = int(sc)
    except Exception:
        sc = 0
    rc = str((b.get('result') or {}).get('returnCode') or '')
    return (sc == 200 and rc == '1' and isinstance(b.get('data'), dict)), sc, b
def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    s = s.replace('â', 'a')
    return re.sub(r'[^0-9a-zçğıöşü ]', ' ', s)
try:
    vars['today_iso'] = today().isoformat()
    vars['card_tries'] = 0
    vars['anger_count'] = 0
    vars['silence_count'] = 0
    vars['email_loaded'] = 'no'
    vars['send_count'] = 0
    vars['cand_json'] = ''
    vars['read_count'] = 0
except Exception as e:
    vars['code_error'] = str(e)[:200]

