CUR = {'TL': ('Türk Lirası', 'lira', 'kuruş'), 'USD': ('Dolar', 'dolar', 'sent'), 'EUR': ('Euro', 'euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'sterlin', 'peni')}
def money(x, c):
    full, unit, sub = CUR[c]
    cents = int(round(abs(float(x)) * 100))
    a, b = divmod(cents, 100)
    if b == 0:
        return words(a) + ' ' + full
    return words(a) + ' ' + unit + ' ' + words(b) + ' ' + sub
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if not d:
        return str(s)
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def suffix_dir(s):
    d = pdate(s)
    last = words(d.year).split()[-1] if d else 'altı'
    vow = [ch for ch in last if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'a'
    hv = {'a': 'ı', 'ı': 'ı', 'e': 'i', 'i': 'i', 'o': 'u', 'u': 'u', 'ö': 'ü', 'ü': 'ü'}[v]
    c = 't' if last[-1] in 'fstkçşhp' else 'd'
    return "'" + c + hv + 'r'
def digits(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
