def body_of(result):
    d = result.get('data') if isinstance(result, dict) else None
    if isinstance(d, str):
        try:
            d = json.loads(d)
        except Exception:
            d = None
    return d if isinstance(d, dict) else {}
def ok_of(result):
    b = body_of(result)
    sc = result.get('status_code') if isinstance(result, dict) else None
    try:
        sc = int(sc)
